// Valid reports whether code is inside the table's range.
func Valid(code int) bool {
	return code >= 1 && code < maxCode
}

// Lookup returns the name of code, or "" and false when it is unknown.
func Lookup(code int) (string, bool) {
	if !Valid(code) {
		return "", false
	}
	n, ok := names[code]
	return n, ok
}
